@dataclass(frozen=True)
class RangeDecision:
    """The result of :func:`assess` over a batch of rounds.

    ``sample_count`` counts every input sample (including outliers),
    ``upper_bound`` is the largest distance among the inliers, and
    ``accepted`` says whether that bound is at most the configured limit.
    """

    sample_count: int
    upper_bound: float
    accepted: bool


@dataclass(frozen=True)
class Observation:
    """One verifier's contribution to a 2D location consensus.

    ``id`` is the verifier's unique non-empty identifier, ``(x, y)`` its
    finite non-bool coordinates, and ``decision`` the :class:`RangeDecision`
    bounding the prover's distance from it. Only the decision's
    ``upper_bound`` (a finite non-negative number) participates in the
    consensus; its ``accepted`` flag never does.
    """

    id: str
    x: float
    y: float
    decision: "RangeDecision"


@dataclass(frozen=True)
class Consensus:
    """The outcome of :func:`locate` over a set of :class:`Observation`.

    ``total`` counts every observation, ``support`` those whose disk covers
    the queried point, ``rejected`` is the lexicographically sorted tuple of
    the non-supporting verifier ids, and ``accepted`` says whether the
    support reaches the requested quorum.
    """

    total: int
    support: int
    rejected: tuple[str, ...]
    accepted: bool


@dataclass(frozen=True, init=False, eq=False)
class ConsensusPolicy:
    """The declared-trust weights used by :func:`locate_weighted`.

    ``weights`` maps each participating verifier id to its positive integer
    weight (stored as a read-only mapping copy) and ``threshold`` is the
    total supporting weight needed for acceptance. The set of weight ids
    must match the observations' ids exactly and ``threshold`` must not
    exceed the sum of all weights.
    """

    weights: Mapping[str, int]
    threshold: int

    def __init__(self, weights: object, threshold: object) -> None:
        if not isinstance(weights, Mapping):
            raise ValueError("weights must be a mapping of id to positive integer")
        try:
            items = list(weights.items())
        except TypeError as error:
            raise ValueError(
                "weights must be a mapping of id to positive integer"
            ) from error
        checked: dict[str, int] = {}
        total_weight = 0
        for ident, weight in items:
            if not isinstance(ident, str) or not ident:
                raise ValueError("weight id must be a non-empty string")
            if ident in checked:
                raise ValueError(f"duplicate weight id: {ident!r}")
            if isinstance(weight, bool) or type(weight) is not int or weight < 1:
                raise ValueError("weight must be a positive integer")
            checked[ident] = weight
            total_weight += weight
        if isinstance(threshold, bool) or type(threshold) is not int or threshold < 1:
            raise ValueError("threshold must be a positive integer")
        if threshold > total_weight:
            raise ValueError("threshold must not exceed the total weight")
        object.__setattr__(self, "weights", MappingProxyType(checked))
        object.__setattr__(self, "threshold", threshold)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ConsensusPolicy):
            return NotImplemented
        return (
            self.threshold == other.threshold
            and dict(self.weights) == dict(other.weights)
        )

    def __hash__(self) -> int:
        return hash((tuple(sorted(self.weights.items())), self.threshold))

    def __repr__(self) -> str:
        return (
            f"ConsensusPolicy(weights={dict(self.weights)!r}, "
            f"threshold={self.threshold!r})"
        )


